mapper.select:

  and m.ruoyi_user_id = #{ruoYiUserId}
order by w.created_at, w.workspace_id
limit #{limit}

mapper.insert:
insert into aden_workspace (
    workspace_id, workspace_name, workspace_status, last_event_seq, version,
    created_by_ruoyi_user_id, created_at, updated_at
) values (
    #{workspaceId}, #{workspaceName}, #{workspaceStatus}, 0, #{version},
    #{createdByRuoYiUserId}, #{createdAt}, #{updatedAt}
)

insert into aden_workspace_member (
    workspace_id, ruoyi_user_id, workspace_role, member_status, version, created_at, updated_at
) values (
    #{workspaceId}, #{ruoYiUserId}, #{workspaceRole}, #{memberStatus}, 0, #{createdAt}, #{updatedAt}
)

insert into aden_audit_event (
    workspace_id, audit_event_id, scope_type, action_code, resource_type, resource_id,
    actor_type, actor_id, correlation_id, outcome, details_json, occurred_at, created_at
) values (
    #{workspaceId}, #{auditEventId}, 'WORKSPACE', #{actionCode}, 'WORKSPACE', #{resourceId},
    'OPERATOR', #{actorId}, #{correlationId}, 'SUCCEEDED', json_object(), #{occurredAt}, #{createdAt}
)

insert into aden_audit_event (
    workspace_id, audit_event_id, scope_type, action_code, resource_type, resource_id,
    actor_type, actor_id, correlation_id, outcome, details_json, occurred_at, created_at
) values (
    null, #{auditEventId}, 'PLATFORM', 'ADEN_WORKSPACE_FORBIDDEN', 'WORKSPACE',
    #{requestedWorkspaceId}, 'OPERATOR', #{actorId}, #{correlationId}, 'REJECTED',
    json_object(), #{occurredAt}, #{createdAt}
)
